 * Invoice history for the billing page.
 */
import { and, desc, eq } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invoices } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvoice } from "./_mappers";
import type { Invoice } from "@/types/billing";
import type { OrgId } from "@/types/common";

export async function listInvoices(
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  const rows = getDb()
    .select()
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .orderBy(desc(invoices.periodStart))
    .all();
  return rows.map(toInvoice);
}

export async function insertInvoice(
  orgId: OrgId,
  invoice: Omit<Invoice, "id" | "createdAt" | "updatedAt">,
): Promise<Invoice> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(invoices)
    .values({
      id: newId(),
      orgId,
      number: invoice.number,
      amountCents: invoice.amountCents,
      currency: invoice.currency,
      periodStart: invoice.periodStart,
      periodEnd: invoice.periodEnd,
      paidAt: invoice.paidAt,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toInvoice(row);
}

export async function findInvoice(
  orgId: OrgId,
  invoiceId: string,
): Promise<Invoice | null> {
  const row = getDb()
    .select()
    .from(invoices)
    .where(and(orgPredicate(invoices.orgId, orgId), eq(invoices.id, invoiceId)))
    .get();
  return row ? toInvoice(row) : null;
}
import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const subscriptions = sqliteTable(
  "subscriptions",
  {
    id: idColumn(),
    ...tenantColumns,
    plan: text("plan", { enum: ["free", "starter", "growth", "enterprise"] })
      .notNull()
      .default("free"),
    interval: text("interval", { enum: ["monthly", "annual"] })
      .notNull()
      .default("monthly"),
    status: text("status", {
      enum: ["trialing", "active", "past_due", "canceled"],
    })
      .notNull()
      .default("trialing"),
    seats: integer("seats").notNull().default(1),
    currentPeriodStart: text("current_period_start").notNull(),
    currentPeriodEnd: text("current_period_end").notNull(),
    cancelAt: text("cancel_at"),
    ...timestampColumns,
  },
  (table) => [index("subscriptions_org_idx").on(table.orgId)],
);

export const invoices = sqliteTable(
  "invoices",
  {
    id: idColumn(),
    ...tenantColumns,
    number: text("number").notNull(),
    amountCents: integer("amount_cents").notNull(),
    currency: text("currency").notNull().default("usd"),
    periodStart: text("period_start").notNull(),
    periodEnd: text("period_end").notNull(),
    paidAt: text("paid_at"),
    ...timestampColumns,
  },
  (table) => [index("invoices_org_period_idx").on(table.orgId, table.periodStart)],
);

export type SubscriptionRow = typeof subscriptions.$inferSelect;
export type NewSubscriptionRow = typeof subscriptions.$inferInsert;
export type InvoiceRow = typeof invoices.$inferSelect;
import type {
  IsoTimestamp,
  OrgId,
  SubscriptionId,
  TenantScoped,
  Timestamps,
} from "./common";

export type PlanId = "free" | "starter" | "growth" | "enterprise";

export const PLAN_IDS: readonly PlanId[] = [
  "free",
  "starter",
  "growth",
  "enterprise",
];

export type BillingInterval = "monthly" | "annual";

export type SubscriptionStatus =
  | "trialing"
  | "active"
  | "past_due"
  | "canceled";

export interface Subscription extends Timestamps, TenantScoped {
  readonly id: SubscriptionId;
  readonly plan: PlanId;
  readonly interval: BillingInterval;
  readonly status: SubscriptionStatus;
  readonly seats: number;
  readonly currentPeriodStart: IsoTimestamp;
  readonly currentPeriodEnd: IsoTimestamp;
  readonly cancelAt: IsoTimestamp | null;
}

/** The resource dimensions every plan caps. Adding a field here ripples into
 *  `PLAN_LIMITS`, `BillingService`, the usage UI and the limit guards. */
export type LimitedResource =
  | "seats"
  | "projects"
  | "issuesPerProject"
  | "storageMb"
  | "apiRequestsPerHour"
