import { toSubscription } from "./_mappers";
import type { BillingInterval, Invoice, PlanId, Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const TRIAL_DAYS = 14;

export async function findSubscription(
  orgId: OrgId,
): Promise<Subscription | null> {
  const row = getDb()
    .select()
    .from(subscriptions)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .get();
  return row ? toSubscription(row) : null;
}

/** New organizations start on a trial period rather than an active plan. */
export async function insertSubscription(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  const now = new Date();
  const stamp = toIsoTimestamp(now);
  const periodEnd = plan === "free"
    ? billingPeriodEnd(now, interval)
    : toIsoTimestamp(new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY));

  const row = getDb()
    .insert(subscriptions)
    .values({
      id: newId(),
      orgId,
      plan,
      interval,
      status: plan === "free" ? "active" : "trialing",
      seats: 1,
      currentPeriodStart: stamp,
      currentPeriodEnd: periodEnd,
      cancelAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toSubscription(row);
}

/** A chosen plan becomes active, retaining any remaining trial dates. */
export async function updateSubscriptionPlan(
  orgId: OrgId,
  plan: PlanId,
  interval: BillingInterval,
): Promise<Subscription> {
  return updateSubscription(orgId, new Date(), () => ({
    patch: { plan, interval, status: "active" },
  }))!.subscription;
}

type SubscriptionPatch = Partial<Pick<Subscription,
  "plan" | "interval" | "status" | "seats" | "currentPeriodStart" |
  "currentPeriodEnd" | "cancelAt"
>>;

/** Read, change and invoice atomically; a no-op callback writes nothing. */
export function updateSubscription(
  orgId: OrgId,
  now: Date,
  change: (current: Subscription) => {
    patch: SubscriptionPatch;
    amountCents?: number;
  } | null,
): { previous: Subscription; subscription: Subscription; invoice: Invoice | null } | null {
  return getDb().transaction((tx) => {
    const row = tx.select().from(subscriptions)
      .where(orgPredicate(subscriptions.orgId, orgId)).get();
    if (!row) throw new Error(`Subscription for org ${orgId} not found`);
    const previous = toSubscription(row);
    const update = change(previous);
    if (update === null) return null;

    const stamp = toIsoTimestamp(now);
    const updated = tx.update(subscriptions)
      .set({ ...update.patch, updatedAt: stamp })
      .where(eq(subscriptions.id, row.id)).returning().get();
    const subscription = toSubscription(updated!);

    if (update.patch.plan !== undefined) {
      tx.update(organizations).set({ plan: subscription.plan, updatedAt: stamp })
        .where(eq(organizations.id, orgId)).run();
    }

    const invoice = (update.amountCents ?? 0) > 0
      ? createPeriodInvoice(orgId, {
          amountCents: update.amountCents!,
          periodStart: subscription.currentPeriodStart,
          periodEnd: subscription.currentPeriodEnd,
        }, now, tx)
      : null;
    return { previous, subscription, invoice };
  });
}

/** Cross-tenant sweep with no page limit, excluding archived workspaces. */
export async function listSubscriptionsDue(
  now: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb().select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(subscriptions.orgId, organizations.id))
    .where(and(
      isNull(organizations.archivedAt),
      or(
        and(eq(subscriptions.status, "active"), lte(subscriptions.currentPeriodEnd, now)),
        and(eq(subscriptions.status, "canceled"), lte(subscriptions.cancelAt, now)),
      ),
    )).all();
  return rows.map(({ subscription }) => toSubscription(subscription));
}

export async function updateSeatCount(
  orgId: OrgId,
  seats: number,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({ seats, updatedAt: toIsoTimestamp(new Date()) })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
export async function cancelSubscription(
  orgId: OrgId,
  cancelAt: IsoTimestamp | null,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      cancelAt,
      status: cancelAt === null ? "active" : "canceled",
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */
export async function listTrialsEndingBefore(
  before: IsoTimestamp,
): Promise<readonly Subscription[]> {
  const rows = getDb()
    .select()
    .from(subscriptions)
    .where(
      and(
        eq(subscriptions.status, "trialing"),
        isNotNull(subscriptions.currentPeriodEnd),
        lte(subscriptions.currentPeriodEnd, before),
        ne(subscriptions.plan, "free"),
      ),
    )
    .all();

  return rows.map(toSubscription);
}
import { billingPeriodEnd } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
