    used: check.used,
  });

  throw new Error(
    `Plan ${check.plan} allows ${check.limit} ${resource}; ${check.used} are in use`,
  );
}

/**
 * A downgrade is refused while the org is over the target plan's quota — the
 * alternative is silently breaking their workspace at the next write.
 */
export async function changePlan(
  actor: Actor,
  input: ChangePlanInput,
): Promise<Subscription> {
  const now = new Date();
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  for (const resource of SUMMARY_RESOURCES) {
    const used = await usageFor(input.orgId, resource);
    if (wouldExceedLimit(input.plan, resource, used, 0)) {
      throw new Error(
        `Cannot move to ${input.plan}: ${used} ${resource} exceeds its limit of ${getLimit(input.plan, resource)}`,
      );
    }
  }

  const change = subscriptionRepo.updateSubscription(input.orgId, now, (current) => {
    const freshPeriod = current.plan === "free" && input.plan !== "free" &&
      current.status !== "trialing";
    const amountCents = freshPeriod
      ? periodCharge(input.plan, current.seats, input.interval)
      : current.status === "active" && current.plan !== "free" && input.plan !== "free"
        ? prorateCharge(
            periodCharge(input.plan, current.seats, current.interval) -
              periodCharge(current.plan, current.seats, current.interval),
            current.currentPeriodStart, current.currentPeriodEnd, now,
          )
        : 0;

    return {
      patch: {
        plan: input.plan,
        interval: input.interval,
        status: "active",
        ...(freshPeriod ? {
          currentPeriodStart: toIsoTimestamp(now),
          currentPeriodEnd: billingPeriodEnd(now, input.interval),
        } : {}),
      },
      amountCents,
    };
  })!;

  if (change.invoice) await publishInvoice(change.invoice, now, actor.userId);

  await emit("billing.plan_changed", {
    ...actorEnvelope(actor),
    occurredAt: toIsoTimestamp(now),
    from: change.previous.plan,
    to: input.plan,
  });

  return change.subscription;
}

export async function updateSeats(
  actor: Actor,
  input: UpdateSeatsInput,
): Promise<Subscription> {
  const now = new Date();
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const change = subscriptionRepo.updateSubscription(input.orgId, now, (current) => {
    if (input.seats > getLimit(current.plan, "seats")) {
      throw new Error(`Plan ${current.plan} tops out at ${getLimit(current.plan, "seats")} seats`);
    }
    return {
      patch: { seats: input.seats },
      amountCents: current.status === "active" && current.plan !== "free"
        ? prorateCharge(
            periodCharge(current.plan, Math.max(0, input.seats - current.seats), current.interval),
            current.currentPeriodStart, current.currentPeriodEnd, now,
          )
        : 0,
    };
  })!;
  if (change.invoice) await publishInvoice(change.invoice, now, actor.userId);
  return change.subscription;
}

export function periodCharge(plan: PlanId, seats: number, interval: BillingInterval): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * (interval === "annual" ? 12 : 1);
}

/** Every persisted charge uses the same event and its audit/notification fan-out. */
export async function publishInvoice(
  invoice: Invoice,
  now: Date,
  actorId: UserId | null = null,
): Promise<void> {
  await emit("billing.invoice_issued", {
    orgId: invoice.orgId,
    actorId,
    occurredAt: toIsoTimestamp(now),
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  });
}

/** Cancels at period end by default; `cancelImmediately` ends it now. */
export async function cancelSubscription(
  actor: Actor,
  input: CancelSubscriptionInput,
): Promise<Subscription> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:manage_billing", billingResource(input.orgId));

  const subscription = requireFound(
    await subscriptionRepo.findSubscription(input.orgId),
    "Subscription",
    input.orgId,
  );

  return subscriptionRepo.cancelSubscription(
    input.orgId,
    input.cancelImmediately
      ? toIsoTimestamp(new Date())
      : subscription.currentPeriodEnd,
  );
}

export async function listInvoices(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly Invoice[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:manage_billing", billingResource(orgId));
  return invoiceRepo.listInvoices(orgId);
}

/**
 * The subscription row is the authority on which plan an org is on; the
 * denormalised `organizations.plan` column is only a display convenience, so
